import{_ as r,o,c as s,a2 as e}from"./chunks/framework.BWuWLRhz.js";const _=JSON.parse('{"title":"搜尋記錄","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/user-guide/settings/history.md","filePath":"zh-HK/user-guide/settings/history.md","lastUpdated":1789222057000}'),n={name:"zh-HK/user-guide/settings/history.md"};function i(a,t,l,g,d,c){return o(),s("div",null,[...t[0]||(t[0]=[e('<h1 id="搜尋記錄" tabindex="-1">搜尋記錄 <a class="header-anchor" href="#搜尋記錄" aria-label="Permalink to &quot;搜尋記錄&quot;">​</a></h1><p>搜尋記錄頁面用於管理 Lertaro 的使用痕跡與智慧推薦權重。頁面頂部包含兩個相互獨立的標籤頁：<strong>搜尋記錄</strong>與<strong>關鍵字記錄</strong>。</p><h2 id="_1-搜尋記錄-search-history" tabindex="-1">1. 搜尋記錄（Search History） <a class="header-anchor" href="#_1-搜尋記錄-search-history" aria-label="Permalink to &quot;1. 搜尋記錄（Search History）&quot;">​</a></h2><p>搜尋記錄追蹤你實際點擊或按 Enter 開啟過的搜尋結果，並將開啟時的「搜尋關鍵字」與「目標實體路徑」進行雙向綁定學習：</p><ul><li><strong>智慧優先召回</strong>：當你之後輸入與先前查詢相似或模糊相關的字元時，Lertaro 會自動在結果列表前列優先召回該檔案。例如，你曾透過輸入 <code>bcomp</code> 開啟過 <code>BCompare.exe</code>，未來只需輸入 <code>bc</code>，該程式依然會被優先推至前排。</li><li><strong>按使用情況排序</strong>：歷史記錄候選會依次按比對起始位置（越靠前越優先）、使用次數（降序）、最近開啟時間（降序）和模糊比對權重排序。此規則只影響歷史記錄候選，其他結果類別的排序保持不變。</li><li><strong>內嵌視窗智慧分區</strong>：在檔案選取對話方塊的內嵌搜尋中，記錄比對項目若屬於當前資料夾內，會自動歸入「當前資料夾」分組，其餘則歸入「全域搜尋」分組。</li><li><strong>失效路徑自動過濾</strong>：若已記錄的檔案或目錄被外部刪除或移動，Lertaro 在檢索時會自動過濾不存在的死鏈，且相同路徑在列表中絕不重複顯示。</li><li><strong>管理操作</strong>： <ul><li><strong>啟用記錄功能</strong>：總開關，關閉後保留現有資料；不會新增記錄，但再次開啟已有項目仍會累計使用次數。</li><li><strong>搜尋過濾</strong>：在上方搜尋框輸入關鍵字快速定位特定記錄項目。</li><li><strong>使用次數與清理</strong>：每筆記錄會顯示開啟次數。選擇次數門檻並按一下<strong>清除少於等於 N 次的記錄</strong>即可清理低頻記錄，也可以刪除單筆記錄或按一下<strong>清空全部記錄</strong>重設所有開啟記錄。</li><li><strong>即時更新</strong>：其他搜尋視窗記錄新的開啟行為後，清單會自動更新使用次數。</li></ul></li></ul><h2 id="_2-關鍵字記錄-keyword-history" tabindex="-1">2. 關鍵字記錄（Keyword History） <a class="header-anchor" href="#_2-關鍵字記錄-keyword-history" aria-label="Permalink to &quot;2. 關鍵字記錄（Keyword History）&quot;">​</a></h2><p>關鍵字記錄用於記憶實際執行過結果或動作，或用於開啟完整視窗的<strong>原始查詢字串</strong>。僅輸入關鍵字後關閉或離開快速搜尋視窗，不會新增記錄：</p><ul><li><strong>熱鍵快速翻閱</strong>：在快速搜尋視窗中，可使用快捷鍵 <strong><code>Alt+Up</code></strong> 向前翻閱、<strong><code>Alt+Down</code></strong> 向後翻閱最近輸入過的搜尋詞；按下 <strong><code>Ctrl+Delete</code></strong> 即可從記錄中直接刪除當前顯示的這條詞彙。</li><li><strong>使用次數與清理</strong>：每個關鍵字會顯示使用次數。選擇次數門檻並按一下<strong>清除少於等於 N 次的記錄</strong>即可清理低頻關鍵字。</li><li><strong>獨立控制與維護</strong>：與搜尋記錄一樣提供專屬的<strong>啟用記錄功能</strong>開關、關鍵字搜尋過濾、單筆刪除與<strong>清空全部記錄</strong>按鈕。關閉後已有關鍵字仍會累計使用次數，但不會加入新關鍵字。</li></ul>',8)])])}const u=r(n,[["render",i]]);export{_ as __pageData,u as default};
